    /**
     * Method to retrieve the Campaign via an CampaignPrimaryKey.
     * @param 	id Long
     * @return 	Campaign
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Campaign handle( FindCampaignQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCampaignId() );
    }
    
    /**
     * Method to retrieve a collection of all Campaigns
     *
     * @param	query	FindAllCampaignQuery 
     * @return 	List<Campaign> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Campaign> handle( FindAllCampaignQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCampaign,
 * but only if the id matches
 *
 * @param		entity	Campaign
 */
	protected void emitFindCampaign( Campaign entity ) {
		LOGGER.info("handling emitFindCampaign" );
		
	    queryUpdateEmitter.emit(FindCampaignQuery.class,
	                            query -> query.getFilter().getCampaignId().equals(entity.getCampaignId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCampaign
	 * 
	 * @param		entity	Campaign
	 */
	protected void emitFindAllCampaign( Campaign entity ) {
		LOGGER.info("handling emitFindAllCampaign" );
		
	    queryUpdateEmitter.emit(FindAllCampaignQuery.class,
	                            query -> true,
	                            entity);
	}

